// 通用 split 函数
vector<string> split(const string& str, const string& delimiter) {
    vector<string> result;
    size_t start = 0;
    size_t end = str.find(delimiter);
    while (end != string::npos) {
        result.push_back(str.substr(start, end - start));
        start = end + delimiter.length();
        end = str.find(delimiter, start);
    }
    // 添加最后一个部分
    result.push_back(str.substr(start));
    return result;
}
​
int main() {
    string s;
    getline(cin, s);
    vector<string> ans = split(s, ",");
    map<string, int> count;
    int n = ans.size();
    // 统计每个数字出现的次数
    for (int i = 0; i < n; i++) {
        count[ans[i]]++;
    }

    vector<int> countArr;
    for (auto p : count) {
        countArr.push_back(p.second);
    }
    // 进行排序
    sort(countArr.begin(), countArr.end());

    int tmpCount = 0;
    int res = 0;
    // 贪心思维优先选取数量最多的
    for (int i = countArr.size() -1; i >= 0; i--) {
        res++;
        tmpCount += countArr[i];
        if (tmpCount >= n /2) {
            break;
        }
    }
​
    cout << res;
    return 0;
}

