package main
​
import (
    "bufio"
    "fmt"
    "os"
    "sort"
    "strings"
)
​
// split 函数，按指定分隔符分割字符串
func split(str, delimiter string) []string {
    return strings.Split(str, delimiter)
}
​
func main() {
    // 读取输入
    reader := bufio.NewReader(os.Stdin)
    line, _ := reader.ReadString('\n')
    line = strings.TrimSpace(line) // 移除首尾空格和换行符
​
    // 按逗号分割输入
    ans := split(line, ",")
    n := len(ans)
​
    // 统计每个数字出现的次数
    count := make(map[string]int)
    for _, num := range ans {
        count[num]++
    }
​
    // 获取所有出现次数，并排序（降序）
    countArr := make([]int, 0, len(count))
    for _, v := range count {
        countArr = append(countArr, v)
    }
    sort.Sort(sort.Reverse(sort.IntSlice(countArr)))
​
    tmpCount := 0
    res := 0
​
    // 贪心思维，优先选择数量最多的
    for _, num := range countArr {
        res++
        tmpCount += num
        if tmpCount >= n/2 {
            break
        }
    }
​
    fmt.Println(res)
}
